<?php
// طرحِ پایگاه‌داده. هر عنصرِ آرایه یک مهاجرت است؛ فقط به انتها اضافه کنید.
declare(strict_types=1);

function pm_schema(): array {
    $E = ' ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci';
    $m1 = [
    // ── هسته
    "CREATE TABLE IF NOT EXISTS settings (k VARCHAR(80) PRIMARY KEY, v MEDIUMTEXT)$E",
    "CREATE TABLE IF NOT EXISTS audit (id BIGINT AUTO_INCREMENT PRIMARY KEY, at DATETIME NOT NULL, user_id INT NULL, user_name VARCHAR(120) NULL,
