        KEY(tbl, rec_id), KEY(at), KEY(user_id))$E",
    "CREATE TABLE IF NOT EXISTS branches (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, address VARCHAR(400) NULL, phone VARCHAR(40) NULL,
        default_wh_id INT NULL, active TINYINT NOT NULL DEFAULT 1)$E",
    "CREATE TABLE IF NOT EXISTS warehouses (id INT AUTO_INCREMENT PRIMARY KEY, branch_id INT NULL, name VARCHAR(120) NOT NULL, province CHAR(2) NOT NULL DEFAULT 'TH',
        num CHAR(2) NOT NULL DEFAULT '01', code CHAR(4) NOT NULL, kind VARCHAR(10) NOT NULL DEFAULT 'own', active TINYINT NOT NULL DEFAULT 1, UNIQUE KEY(code))$E",
    "CREATE TABLE IF NOT EXISTS cashboxes (id INT AUTO_INCREMENT PRIMARY KEY, branch_id INT NOT NULL, name VARCHAR(120) NOT NULL, pos_terminal VARCHAR(120) NULL,
        bank_account_id INT NULL, transfer_account_id INT NULL, active TINYINT NOT NULL DEFAULT 1)$E",
    "CREATE TABLE IF NOT EXISTS fiscal_years (id INT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(60) NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL,
        vat_pct DECIMAL(5,2) NOT NULL DEFAULT 10, rounding VARCHAR(10) NOT NULL DEFAULT 'floor', currency VARCHAR(10) NOT NULL DEFAULT 'IRR', active TINYINT NOT NULL DEFAULT 1)$E",
    "CREATE TABLE IF NOT EXISTS fiscal_locks (ym CHAR(7) PRIMARY KEY, locked_by INT NULL, locked_at DATETIME NOT NULL)$E",
    "CREATE TABLE IF NOT EXISTS holidays (id INT AUTO_INCREMENT PRIMARY KEY, d DATE NULL, jmd CHAR(5) NULL, title VARCHAR(200) NOT NULL, source VARCHAR(20) NOT NULL DEFAULT 'manual', KEY(d))$E",
    "CREATE TABLE IF NOT EXISTS fx_rates (id INT AUTO_INCREMENT PRIMARY KEY, d DATE NOT NULL, cur CHAR(3) NOT NULL DEFAULT 'USD', rate BIGINT NOT NULL, source VARCHAR(40) NOT NULL, created_at DATETIME NOT NULL, KEY(d))$E",
    // ── کاربران
    "CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(60) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, mobile VARCHAR(15) NULL UNIQUE,
        pass_hash VARCHAR(255) NULL, is_super TINYINT NOT NULL DEFAULT 0, active TINYINT NOT NULL DEFAULT 1, kind VARCHAR(10) NOT NULL DEFAULT 'staff',
        max_discount_pct DECIMAL(5,2) NOT NULL DEFAULT 0, max_credit BIGINT NOT NULL DEFAULT 0, employee_id INT NULL, created_at DATETIME NOT NULL, last_login DATETIME NULL)$E",
    "CREATE TABLE IF NOT EXISTS roles (id INT AUTO_INCREMENT PRIMARY KEY, slug VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(80) NOT NULL, builtin TINYINT NOT NULL DEFAULT 0)$E",
    "CREATE TABLE IF NOT EXISTS role_caps (role_id INT NOT NULL, cap VARCHAR(60) NOT NULL, PRIMARY KEY(role_id, cap))$E",
    "CREATE TABLE IF NOT EXISTS user_roles (user_id INT NOT NULL, role_id INT NOT NULL, PRIMARY KEY(user_id, role_id))$E",
    "CREATE TABLE IF NOT EXISTS user_branches (user_id INT NOT NULL, branch_id INT NOT NULL, PRIMARY KEY(user_id, branch_id))$E",
    "CREATE TABLE IF NOT EXISTS rate_hits (k VARCHAR(120) NOT NULL, at DATETIME NOT NULL, KEY(k, at))$E",
    "CREATE TABLE IF NOT EXISTS otp_codes (id INT AUTO_INCREMENT PRIMARY KEY, mobile VARCHAR(15) NOT NULL, purpose VARCHAR(20) NOT NULL, code_hash VARCHAR(255) NOT NULL,
