    "CREATE TABLE IF NOT EXISTS sms_log (id INT AUTO_INCREMENT PRIMARY KEY, at DATETIME NOT NULL, mobile VARCHAR(15) NOT NULL, kind VARCHAR(20) NOT NULL, ref_type VARCHAR(20) NULL, ref_id INT NULL,
        tpl_key VARCHAR(40) NULL, tpl_id VARCHAR(20) NULL, params MEDIUMTEXT NULL, ok TINYINT NOT NULL DEFAULT 0, msg VARCHAR(300) NULL, raw TEXT NULL, retryable TINYINT NOT NULL DEFAULT 0,
