    "CREATE TABLE IF NOT EXISTS passkeys (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, cred_id VARCHAR(255) NOT NULL UNIQUE, pubkey TEXT NOT NULL, alg INT NOT NULL,
