    "CREATE TABLE IF NOT EXISTS purchase_orders (id INT AUTO_INCREMENT PRIMARY KEY, number VARCHAR(30) NULL, supplier_id INT NOT NULL, warehouse_id INT NOT NULL, status VARCHAR(12) NOT NULL DEFAULT 'draft',
