    "CREATE TABLE IF NOT EXISTS purchase_order_items (id INT AUTO_INCREMENT PRIMARY KEY, po_id INT NOT NULL, product_id INT NOT NULL, variant_id INT NULL, qty INT NOT NULL, unit_price BIGINT NOT NULL, KEY(po_id))$E",
    "CREATE TABLE IF NOT EXISTS goods_receipts (id INT AUTO_INCREMENT PRIMARY KEY, po_id INT NULL, supplier_id INT NOT NULL, warehouse_id INT NOT NULL, d DATE NOT NULL, status VARCHAR(12) NOT NULL DEFAULT 'open',
        report VARCHAR(500) NULL, created_by INT NULL, created_at DATETIME NOT NULL)$E",
    "CREATE TABLE IF NOT EXISTS goods_receipt_items (id INT AUTO_INCREMENT PRIMARY KEY, gr_id INT NOT NULL, po_item_id INT NULL, product_id INT NOT NULL, variant_id INT NULL, qty_ordered INT NOT NULL DEFAULT 0,
        qty INT NOT NULL, unit_price BIGINT NOT NULL DEFAULT 0, KEY(gr_id))$E",
    "CREATE TABLE IF NOT EXISTS purchase_invoices (id INT AUTO_INCREMENT PRIMARY KEY, gr_id INT NULL, supplier_id INT NOT NULL, number VARCHAR(40) NULL, d DATE NOT NULL, due_date DATE NULL,
        subtotal BIGINT NOT NULL, overhead BIGINT NOT NULL DEFAULT 0, tax BIGINT NOT NULL DEFAULT 0, total BIGINT NOT NULL, status VARCHAR(12) NOT NULL DEFAULT 'posted', created_by INT NULL, created_at DATETIME NOT NULL)$E",
    "CREATE TABLE IF NOT EXISTS purchase_invoice_items (id INT AUTO_INCREMENT PRIMARY KEY, pi_id INT NOT NULL, product_id INT NOT NULL, variant_id INT NULL, qty INT NOT NULL, unit_price BIGINT NOT NULL,
