    // ── انبار
    "CREATE TABLE IF NOT EXISTS lots (id INT AUTO_INCREMENT PRIMARY KEY, product_id INT NOT NULL, variant_id INT NULL, warehouse_id INT NOT NULL, seller_code CHAR(2) NOT NULL DEFAULT '00',
