    "CREATE TABLE IF NOT EXISTS wh_units (id INT AUTO_INCREMENT PRIMARY KEY, lot_id INT NOT NULL, code CHAR(33) NOT NULL UNIQUE, status VARCHAR(10) NOT NULL DEFAULT 'labeled', unit_cost BIGINT NOT NULL DEFAULT 0,
