    "CREATE TABLE IF NOT EXISTS stock_moves (id BIGINT AUTO_INCREMENT PRIMARY KEY, lot_id INT NOT NULL, unit_id INT NULL, product_id INT NOT NULL, variant_id INT NULL, warehouse_id INT NOT NULL,
