    "CREATE TABLE IF NOT EXISTS stock_reservations (id INT AUTO_INCREMENT PRIMARY KEY, cart_id INT NULL, sale_id INT NULL, cashbox_id INT NULL, lot_id INT NULL, unit_id INT NULL, product_id INT NOT NULL,
