    "CREATE TABLE IF NOT EXISTS stock_losses (id INT AUTO_INCREMENT PRIMARY KEY, kind VARCHAR(12) NOT NULL, lot_id INT NOT NULL, qty INT NOT NULL, amount BIGINT NOT NULL, bearer VARCHAR(10) NOT NULL DEFAULT 'store',
        reason VARCHAR(400) NOT NULL, units MEDIUMTEXT NULL, confirmed_by INT NULL, created_at DATETIME NOT NULL)$E",
    // ── برچسب و چاپ
    "CREATE TABLE IF NOT EXISTS label_templates (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, kind VARCHAR(10) NOT NULL DEFAULT 'item', w_mm DECIMAL(6,1) NOT NULL, h_mm DECIMAL(6,1) NOT NULL,
        layout MEDIUMTEXT NOT NULL, is_default TINYINT NOT NULL DEFAULT 0)$E",
    "CREATE TABLE IF NOT EXISTS print_stations (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, token_hash CHAR(64) NOT NULL, printers MEDIUMTEXT NULL, papers MEDIUMTEXT NULL,
