    "CREATE TABLE IF NOT EXISTS print_jobs (id INT AUTO_INCREMENT PRIMARY KEY, station_id INT NOT NULL, printer VARCHAR(200) NULL, url VARCHAR(600) NOT NULL, paper_w DECIMAL(6,1) NOT NULL, paper_h DECIMAL(6,1) NOT NULL,
