        UNIQUE KEY(open_key), KEY(cashbox_id, status))$E",
    "CREATE TABLE IF NOT EXISTS carts (id INT AUTO_INCREMENT PRIMARY KEY, token CHAR(32) NOT NULL UNIQUE, shift_id INT NULL, cashbox_id INT NULL, user_id INT NOT NULL, customer_id INT NULL,
