    "CREATE TABLE IF NOT EXISTS cart_items (id INT AUTO_INCREMENT PRIMARY KEY, cart_id INT NOT NULL, product_id INT NOT NULL, variant_id INT NULL, unit_id INT NULL, qty INT NOT NULL, price BIGINT NOT NULL,
