    "CREATE TABLE IF NOT EXISTS sales (id INT AUTO_INCREMENT PRIMARY KEY, number VARCHAR(30) NULL, cart_token CHAR(32) NULL UNIQUE, channel_id INT NULL, branch_id INT NULL, cashbox_id INT NULL, shift_id INT NULL,
