    "CREATE TABLE IF NOT EXISTS sale_items (id INT AUTO_INCREMENT PRIMARY KEY, sale_id INT NOT NULL, product_id INT NOT NULL, variant_id INT NULL, title VARCHAR(250) NOT NULL, qty INT NOT NULL, price BIGINT NOT NULL,
