    "CREATE TABLE IF NOT EXISTS sale_returns (id INT AUTO_INCREMENT PRIMARY KEY, sale_id INT NOT NULL, shift_id INT NULL, user_id INT NOT NULL, reason VARCHAR(400) NOT NULL, amount BIGINT NOT NULL, tax BIGINT NOT NULL DEFAULT 0,
