    "CREATE TABLE IF NOT EXISTS doc_revisions (id INT AUTO_INCREMENT PRIMARY KEY, doc_id INT NOT NULL, revision INT NOT NULL, data MEDIUMTEXT NOT NULL, hash CHAR(64) NOT NULL, user_id INT NULL, at DATETIME NOT NULL, KEY(doc_id))$E",
    "CREATE TABLE IF NOT EXISTS doc_counters (k VARCHAR(40) PRIMARY KEY, last INT NOT NULL DEFAULT 0)$E",
    "CREATE TABLE IF NOT EXISTS doc_shares (id INT AUTO_INCREMENT PRIMARY KEY, doc_id INT NOT NULL, token CHAR(32) NOT NULL UNIQUE, pass_hash VARCHAR(255) NULL, expires_at DATETIME NULL, views INT NOT NULL DEFAULT 0,
