    "CREATE TABLE IF NOT EXISTS doc_payments (id INT AUTO_INCREMENT PRIMARY KEY, doc_id INT NOT NULL, amount BIGINT NOT NULL, d DATE NOT NULL, ref VARCHAR(120) NULL, created_by INT NULL, created_at DATETIME NOT NULL, KEY(doc_id))$E",
