    "CREATE TABLE IF NOT EXISTS commission_lines (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, sale_id INT NOT NULL, sale_item_id INT NULL, return_id INT NULL, amount BIGINT NOT NULL, ym CHAR(7) NOT NULL,
