    "CREATE TABLE IF NOT EXISTS leaves (id INT AUTO_INCREMENT PRIMARY KEY, employee_id INT NOT NULL, kind VARCHAR(12) NOT NULL DEFAULT 'paid', from_d DATE NOT NULL, to_d DATE NOT NULL, days DECIMAL(5,2) NOT NULL,
