    "CREATE TABLE IF NOT EXISTS payslips (id INT AUTO_INCREMENT PRIMARY KEY, employee_id INT NOT NULL, ym CHAR(7) NOT NULL, items MEDIUMTEXT NOT NULL, gross BIGINT NOT NULL, deductions BIGINT NOT NULL, net BIGINT NOT NULL,
