    "CREATE TABLE IF NOT EXISTS wallet_ledger (id INT AUTO_INCREMENT PRIMARY KEY, customer_id INT NOT NULL, amount BIGINT NOT NULL, kind VARCHAR(12) NOT NULL, ref_type VARCHAR(20) NULL, ref_id INT NULL,
