    "CREATE TABLE IF NOT EXISTS calls (id INT AUTO_INCREMENT PRIMARY KEY, customer_id INT NOT NULL, user_id INT NULL, at DATETIME NOT NULL, direction VARCHAR(4) NOT NULL DEFAULT 'out', result VARCHAR(20) NOT NULL,
